import React, { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import {
  FaSearch,
  FaLaptop,
  FaKey,
  FaWallet,
  FaBook,
  FaShoppingBag,
  FaIdCard,
  FaWineBottle,
  FaBoxOpen,
  FaArrowRight,
  FaMapMarkerAlt,
  FaCalendarAlt,
} from "react-icons/fa";
import "../styles/Home.css";

function Home() {
  const [user, setUser] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("All");

  const categories = [
    "All",
    "Watch",
    "Laptop",
    "Bag",
    "Books",
    "ID Cards",
    "Keys",
    "Wallet",
    "Electronics",
    "Clothes",
    "Bottle",
    "Others",
  ];

  const categoryIcons = {
    Watch: "⌚",
    Laptop: <FaLaptop />,
    Bag: <FaShoppingBag />,
    Books: <FaBook />,
    "ID Cards": <FaIdCard />,
    Keys: <FaKey />,
    Wallet: <FaWallet />,
    Electronics: "💻",
    Clothes: "👕",
    Bottle: <FaWineBottle />,
    Others: <FaBoxOpen />,
  };

  const [recentItems] = useState([
    {
      id: 1,
      title: "Apple MacBook Pro",
      category: "Laptop",
      location: "Library Floor 2",
      date: "Oct 24, 2026",
      image:
        "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80",
    },
    {
      id: 2,
      title: "Casio Analog Watch",
      category: "Watch",
      location: "Cafeteria",
      date: "Oct 23, 2026",
      image:
        "https://images.unsplash.com/photo-1524592094714-0f0654e20314?auto=format&fit=crop&w=800&q=80",
    },
    {
      id: 3,
      title: "Black Nike Backpack",
      category: "Bag",
      location: "Computer Lab 4",
      date: "Oct 22, 2026",
      image:
        "https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80",
    },
    {
      id: 4,
      title: "Student ID Card",
      category: "ID Cards",
      location: "Main Gate",
      date: "Oct 21, 2026",
      image:
        "https://images.unsplash.com/photo-1593640408182-31c70c8268f5?auto=format&fit=crop&w=800&q=80",
    },
  ]);

  useEffect(() => {
    const userData = localStorage.getItem("user");
    if (userData) {
      setUser(JSON.parse(userData));
    }
  }, []);

  const greeting = useMemo(() => {
    const hour = new Date().getHours();

    if (hour < 12) return "Good Morning";
    if (hour < 18) return "Good Afternoon";

    return "Good Evening";
  }, []);

  const filteredItems = recentItems.filter((item) => {
    const matchesCategory =
      activeCategory === "All" || item.category === activeCategory;

    const matchesSearch =
      item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.location.toLowerCase().includes(searchQuery.toLowerCase());

    return matchesCategory && matchesSearch;
  });

  const stats = [
    {
      title: "Found Items",
      value: filteredItems.length,
      icon: "📦",
    },
    {
      title: "Categories",
      value: categories.length - 1,
      icon: "🏷️",
    },
    {
      title: "Welcome",
      value: user ? user.name : "Guest",
      icon: "👋",
    },
  ];

  return (
    <div className="home-page">

      <section className="dashboard-hero">

        <div className="hero-left">

          <span className="welcome-badge">
            {greeting}
          </span>

          <h1>
            {user ? user.name : "Guest"} 👋
          </h1>

          <p>
            Search and recover lost belongings across your campus in seconds.
          </p>

          <div className="search-bar-container">

            <FaSearch className="search-icon" />

            <input
              className="search-input"
              placeholder="Search items or locations..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />

          </div>

        </div>

        <div className="hero-right">

          {stats.map((stat) => (

            <div className="stat-card" key={stat.title}>

              <div className="stat-icon">
                {stat.icon}
              </div>

              <h2>{stat.value}</h2>

              <p>{stat.title}</p>

            </div>

          ))}

        </div>

      </section>

      <section className="category-section">

        <div className="section-header">

          <h2>Browse Categories</h2>

        </div>

        <div className="category-pills">

          {categories.map((cat) => (

            <button
              key={cat}
              className={`category-pill ${
                activeCategory === cat ? "active" : ""
              }`}
              onClick={() => setActiveCategory(cat)}
            >

              <span className="category-icon">

                {cat === "All" ? "✨" : categoryIcons[cat]}

              </span>

              {cat}

            </button>

          ))}

        </div>

      </section>

      <section className="recent-items-section">

        <div className="section-header">

          <h2>Recently Found</h2>

        </div>

        {filteredItems.length === 0 ? (

          <div className="empty-message">

            No matching items found.

          </div>

        ) : (

          <div className="card-grid">

            {filteredItems.map((item) => (

              <div className="item-card" key={item.id}>

                <div className="card-image">

                  <img
                    src={item.image}
                    alt={item.title}
                  />

                  <span className="badge">
                    Found
                  </span>

                </div>

                <div className="card-body">

                  <span className="category-label">
                    {item.category}
                  </span>

                  <h3>{item.title}</h3>

                  <div className="card-info">

                    <p>

                      <FaMapMarkerAlt />

                      {item.location}

                    </p>

                    <p>

                      <FaCalendarAlt />

                      {item.date}

                    </p>

                  </div>

                  <Link
                    to={`/item/${item.id}`}
                    className="details-btn"
                  >

                    View Details

                    <FaArrowRight />

                  </Link>

                </div>

              </div>

            ))}

          </div>

        )}

      </section>

    </div>
  );
}

export default Home;
